package com.crms.config;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.web.servlet.config.annotation.CorsRegistry;import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;@Configuration public class CorsConfig{@Bean WebMvcConfigurer cors(@Value("${app.frontend-origin}")String origin){return new WebMvcConfigurer(){public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOrigins(origin).allowedMethods("GET","POST","PUT","PATCH","DELETE","OPTIONS").allowedHeaders("*");}};}}
